#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, k;
    cin >> n >> k;

    vector<bool> visited(n + 1, false);
    vector<int> adj(n);
    for (int i = 0; i < n; ++i) {
        adj[i] = (i * k) % n;
    }

    function<void(int)> dfs = [&](int n) {
        visited[n] = true;
        while (!visited[adj[n]]) {
            n = adj[n];
            visited[n] = true;
        }
    };

    int pairs = 0;
    for (int i = 1; i < n; ++i) {
        if (!visited[i]) {
            dfs(i);
            pairs++;
        }
    }

    const long long mod = 1000000007;
    long long result;
    if (k == 1) {
        // pow(n, n, mod)
        long long base = n;
        long long exp = n;
        long long res = 1;
        while (exp > 0) {
            if (exp & 1) res = (res * base) % mod;
            base = (base * base) % mod;
            exp >>= 1;
        }
        result = res;
    } else {
        // pow(n, pairs, mod)
        long long base = n;
        long long exp = pairs;
        long long res = 1;
        while (exp > 0) {
            if (exp & 1) res = (res * base) % mod;
            base = (base * base) % mod;
            exp >>= 1;
        }
        result = res;
    }

    cout << result << "\n";

    return 0;
}
